function renameFavorite(input){
 const list=favorites(),entry=list.find(q=>q.id===input.dataset.favoriteName);if(!entry)return;const previous=favoriteName(entry),name=cleanPresetName(input.value,previous);input.value=name;if(name===previous)return;entry.name=name;
 try{writeFavorites(list);const card=input.closest('.gallery-card'),open=card.querySelector('[data-favorite-id]');open.title='Apri '+name;open.setAttribute('aria-label','Apri '+name);card.querySelector('img').alt=name;card.querySelector('[data-export-favorite]').setAttribute('aria-label','Esporta preset '+name);card.querySelector('[data-remove-favorite]').setAttribute('aria-label','Rimuovi '+name);input.setAttribute('aria-label','Nome della creazione '+name);toast('Nome salvato');}catch{input.value=previous;toast('Non posso salvare il nome: libera spazio nel browser.');}
}
