$('#gallery-grid').onclick=e=>{
 const remove=e.target.closest('[data-remove-favorite]');if(remove){try{writeFavorites(favorites().filter(q=>q.id!==remove.dataset.removeFavorite));showGallery();}catch{toast('Non posso aggiornare la galleria.');}return;}
 const exportButton=e.target.closest('[data-export-favorite]');if(exportButton){const q=favorites().find(q=>q.id===exportButton.dataset.exportFavorite);if(q)exportPreset({...q,name:favoriteName(q)});return;}
 const b=e.target.closest('[data-favorite-id]');if(!b)return;const q=favorites().find(q=>q.id===b.dataset.favoriteId);if(!q)return;try{remember();adopt(normalizeCreation(q.state),favoriteName(q),q);$('#gallery-dialog').close();}catch{toast('Non posso aprire questa creazione.');}
};
